function wsWhatsNewInto(box, md) {
  let list = null;
  for (const raw of md.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) {
      list = null;
      continue;
    }
    const h = /^#{1,6}\s+(.*)$/.exec(line);
    if (h) {
      box.createEl("h4", { text: h[1] });
      list = null;
      continue;
    }
    const li = /^[-*]\s+(.*)$/.exec(line);
    if (li) {
      if (!list)
        list = box.createEl("ul");
      list.createEl("li", { text: li[1] });
      continue;
    }
    box.createEl("p", { text: line });
    list = null;
  }
}
