function wsInternalView(app, type, ask) {
  try {
    const leaves = app.workspace.getLeavesOfType(type) || [];
    for (const l of leaves) {
      if (!l || l.isDeferred)
        continue;
      if (l.view)
        return !!ask(l.view);
    }
  } catch {
    return null;
  }
  return null;
}
