var WsPropSuggestModal = import_obsidian2.FuzzySuggestModal ? class extends import_obsidian2.FuzzySuggestModal {
  constructor(app, items, onPick, placeholder, newLabel, taken) {
    super(app);
    this._items = items;
    this._onPick = onPick;
    this._newLabel = newLabel || "";
    this._taken = taken || items;
    if (this.setPlaceholder) {
      this.setPlaceholder(placeholder || wsT("Which property should become a column?"));
    }
  }
  getItems() {
    if (!this._newLabel)
      return this._items;
    let q = "";
    try {
      q = String(this.inputEl && this.inputEl.value || "").trim();
    } catch {
      q = "";
    }
    if (!q)
      return this._items;
    const lower = q.toLowerCase();
    for (const it of this._taken) {
      if (String(it && it.label || "").toLowerCase() === lower)
        return this._items;
      if (String(it && it.key || "").toLowerCase() === lower)
        return this._items;
    }
    return this._items.concat([{
      key: q,
      label: this._newLabel.replace("%s", q),
      isNew: true
    }]);
  }
  getItemText(item) {
    if (typeof item.n !== "number")
      return item.label;
    return item.label + "  ·  " + (item.n === 1 ? wsT("{n} note", { n: item.n }) : wsT("{n} notes", { n: item.n })) + ((item.spellings || 0) > 1 ? "  ·  " + wsT("{n} spellings", { n: item.spellings || 0 }) : "");
  }
  onChooseItem(item) {
    this._onPick(item);
  }
} : null;
